    def test_input_is_not_mutated(self) -> None:
        source = [(1, 5), (3, 7)]
        merge_intervals(source)
        self.assertEqual(source, [(1, 5), (3, 7)])

    def test_a_generator_is_accepted(self) -> None:
        pairs = [(1, 5), (3, 7)]
